import{_ as t,a,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse('{"title":"第一册：英语初阶 · Lesson 94 When did you or will you go ...?","description":"学习 过去、现在与将来的时间线，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 94 When did you or will you go ...?","description":"学习 过去、现在与将来的时间线，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 过去、现在与将来的时间线，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 93 Our new neighbour","link":"/life/english/new-concept/book-1/unit-04/lesson-093"},"next":{"text":"第一册：英语初阶 · Lesson 95 Tickets, please.","link":"/life/english/new-concept/book-1/unit-04/lesson-095"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 93 Our new neighbour","link":"/life/english/new-concept/book-1/unit-04/lesson-093"},"next":{"text":"第一册：英语初阶 · Lesson 95 Tickets, please.","link":"/life/english/new-concept/book-1/unit-04/lesson-095"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-04/lesson-094.md","filePath":"life/english/new-concept/book-1/unit-04/lesson-094.md"}'),l={name:"life/english/new-concept/book-1/unit-04/lesson-094.md"};function i(r,e,s,d,h,c){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第一册-英语初阶-·-lesson-94-when-did-you-or-will-you-go" tabindex="-1">第一册：英语初阶 · Lesson 94 When did you or will you go ...? <a class="header-anchor" href="#第一册-英语初阶-·-lesson-94-when-did-you-or-will-you-go" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 94 When did you or will you go ...?&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-04/overview">单元 4</a> · <a href="/life/english/new-concept/book-1/unit-04/lesson-093">配套课 Lesson 93</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>比较过去经历与未来计划 本课要掌握过去、现在与将来的时间线，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。本课将前一课的结构迁移到另一个例子；请先口头作答，再写出完整句子，不只替换单个单词。</p><p>本课为配套句型训练；先回顾相邻奇数课，再独立完成本页的原创练习。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>pilot</td><td>/ˈpaɪlət/</td><td>n.</td><td>飞行员</td><td>an airline pilot</td></tr><tr><td>station</td><td>/ˈsteɪʃn/</td><td>n.</td><td>车站</td><td>at the station</td></tr><tr><td>return</td><td>/rɪˈtɜːn/</td><td>v.</td><td>返回</td><td>return tomorrow</td></tr><tr><td>next</td><td>/nekst/</td><td>adj.</td><td>下一个的</td><td>next month</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>last year — 已结束的过去</li><li>next week — 将来的时间</li></ul><h2 id="语法讲解-过去、现在与将来的时间线" tabindex="-1">语法讲解：过去、现在与将来的时间线 <a class="header-anchor" href="#语法讲解-过去、现在与将来的时间线" aria-label="Permalink to &quot;语法讲解：过去、现在与将来的时间线&quot;">​</a></h2><p>先确定时间再选动词形式：过去 go→went，未来 will go，现在习惯 go/goes。问过去用 did + 原形，问未来用 will + 原形。tomorrow、last year 等时间词提供线索，但要结合整个叙述。多句对比中，人称变化和时态变化是两个独立检查项，不能只改时间词而保留错误谓语。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>He will return next Tuesday.</p></blockquote><p>他将在下周二回来。</p><p>Will return 为将来结构，return 用原形；next Tuesday 前不用 on。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>did 和 will 后都接原形，但表达的时间不同；不能把 Did he go tomorrow? 当正常将来问句。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“He will return next Tuesday.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>He will return next Tuesday. Our neighbour flew to Madrid last week.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“比较过去经历与未来计划”写两至三句，再读给同伴听。至少使用一次过去、现在与将来的时间线，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>Will return 为将来结构，return 用原形；next Tuesday 前不用 on。 Flew 是 fly 的过去式，last week 指明确过去；to Madrid 表飞行目的地。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>补将来助动词：He ___ return next Tuesday.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> will</p><p><strong>解析：</strong> 按本课规则判断：先确定时间再选动词形式：过去 go→went，未来 will go，现在习惯 go/goes。问过去用 did + 原形，问未来用 will + 原形。tomorrow、last year 等时间词提供线索，但要结合整个叙述。多句对比中，人称变化和时态变化是两个独立检查项，不能只改时间词而保留错误谓语。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“他将在下周二回来。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> He will return next Tuesday.</p><p><strong>解析：</strong> Will return 为将来结构，return 用原形；next Tuesday 前不用 on。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：Our neighbour flew to Madrid last week.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 我们的邻居上周飞去了马德里。</p><p><strong>解析：</strong> Flew 是 fly 的过去式，last week 指明确过去；to Madrid 表飞行目的地。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：过去、现在与将来的时间线。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-04/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-04/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-04/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-04/lesson-093">上一课</a> · <a href="/life/english/new-concept/book-1/unit-04/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-04/lesson-095">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const g=t(l,[["render",i]]);export{p as __pageData,g as default};
